import { uniqueName, expect, test } from "../../fixtures";

const POLL_INTERVAL_MS = 500;
const POLL_TIMEOUT_MS = 60_000;

/** Returns an ISO date (YYYY-MM-DD) that is `days` days from today in UTC. */
function isoDateInDays(days: number): string {
  const d = new Date();
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** Builds a plain-text insurance certificate that states the given expiry date. */
function insuranceCertificate(expiresOn: string, vendorName: string): Buffer {
  const text = [
    "CERTIFICATE OF INSURANCE",
    `Insured: ${vendorName}`,
    "Policy Number: GL-100234",
    "Effective Date: 2024-01-01",
    `Expiration Date: ${expiresOn}`,
  ].join("\n");
  return Buffer.from(text, "utf-8");
}

const EXAMPLES: Array<{ days: number; include: boolean }> = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

test.describe("insurance expiry flag", () => {
  for (const { days, include } of EXAMPLES) {
    const label = include ? "include" : "do not include";

    test(
      `insurance expiring in ${days} days: vendor ${label} insurance_expiring_soon`,
      { tag: "@REV-08" },
      async ({ apiAs }) => {
        // Arrange
        const member = await apiAs("member");
        const vendorName = uniqueName(`Expiry ${days}d`);

        const createResponse = await member.post("/api/vendors", {
          data: {
            name: vendorName,
            category: "services",
            contact_email: `ops+${days}-${Date.now().toString(36)}@example.test`,
          },
        });
        expect(createResponse.status()).toBe(201);
        const vendor = await createResponse.json();

        const expiresOn = isoDateInDays(days);
        const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "insurance.txt",
              mimeType: "text/plain",
              buffer: insuranceCertificate(expiresOn, vendorName),
            },
          },
        });
        expect(uploadResponse.status()).toBe(201);
        const document = await uploadResponse.json();

        // Wait for extraction to finish before checking flags.
        const deadline = Date.now() + POLL_TIMEOUT_MS;
        let documentStatus = document.status as string;
        while (documentStatus === "processing" && Date.now() < deadline) {
          await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
          const poll = await member.get(`/api/documents/${document.id}`);
          expect(poll.status()).toBe(200);
          documentStatus = (await poll.json()).status;
        }
        expect(documentStatus).toBe("extracted");

        // Act
        const response = await member.get(`/api/vendors/${vendor.id}`);

        // Assert
        expect(response.status()).toBe(200);
        const body = await response.json();
        if (include) {
          expect(body.flags).toContain("insurance_expiring_soon");
        } else {
          expect(body.flags).not.toContain("insurance_expiring_soon");
        }
      },
    );
  }
});
